namespace FastIoC.Core
{
    /// <summary>
    /// Optional facts about the generated code, so the runtime can skip work it doesn't need.
    /// Implemented by generated modules from this version on. Code generated by earlier versions
    /// doesn't implement it, and the runtime then takes the slower general paths.
    /// </summary>
    public interface IGeneratedModuleFeatures
    {
        /// <summary>
        /// Gets the recipe of a scene that has its own bindings.
        /// Returns false for scenes that only use global bindings, without allocating anything.
        /// </summary>
        bool TryGetSceneRecipe(string sceneName, out RecipeActivator[] activators, out Lifetime[] lifetimes);

        /// <summary>True if any MonoBehaviour has local (same hierarchy) references to fill on instantiation.</summary>
        bool HasLocalInjectors { get; }

        /// <summary>True if any MonoBehaviour implements IInjectableForChildren&lt;T&gt;.</summary>
        bool HasDataInjectors { get; }
    }
}
